        public static readonly ulong perlin = new ustring("perlin").hash();
        public static readonly ulong snoise = new ustring("snoise").hash();
        public static readonly ulong simplexnoise = new ustring("simplexnoise").hash();
        public static readonly ulong simplex = new ustring("simplex").hash();
        public static readonly ulong usimplexnoise = new ustring("usimplexnoise").hash();
        public static readonly ulong usimplex = new ustring("usimplex").hash();
        public static readonly ulong cell = new ustring("cell").hash();
        public static readonly ulong gabor = new ustring("gabor").hash();
        public static readonly ulong @null = new ustring("null").hash();
        public static readonly ulong unull = new ustring("unull").hash();
        public static readonly ulong hash = new ustring("hash").hash();
    }

