        // Called with the noise name when a generic noise function is given an unknown name
        public static Action<ulong> unknown_noise_type_hook;

        // SimplexNoise / USimplexNoise (oslnoise.h) for float results
        private static float simplex_noise(bool unsigned_result, int seed, float c0)
        {
            float r = SimplexNoiseFuncs.simplexnoise1(c0, seed);
            return unsigned_result ? 0.5f * (r + 1.0f) : r;
        }

        private static float simplex_noise(bool unsigned_result, int seed, float c0, float c1)
        {
            float r = SimplexNoiseFuncs.simplexnoise2(c0, c1, seed);
            return unsigned_result ? 0.5f * (r + 1.0f) : r;
        }

        private static float simplex_noise(bool unsigned_result, int seed, float c0, float c1, float c2)
        {
            float r = SimplexNoiseFuncs.simplexnoise3(c0, c1, c2, seed);
            return unsigned_result ? 0.5f * (r + 1.0f) : r;
        }

        private static float simplex_noise(bool unsigned_result, int seed, float c0, float c1, float c2, float c3)
        {
            float r = SimplexNoiseFuncs.simplexnoise4(c0, c1, c2, c3, seed);
            return unsigned_result ? 0.5f * (r + 1.0f) : r;
        }

        // The Dual2 forms: the derivatives come from the gradient of the noise (sums are ((a + b) + c) + d)
        private static Dual2f simplex_noise_dual(bool unsigned_result, int seed, Dual2f c0)
        {
            float dnd0;
            float r = SimplexNoiseFuncs.simplexnoise1(c0.x, seed, &dnd0);
            if (unsigned_result)
            {
                r = 0.5f * (r + 1.0f);
                dnd0 *= 0.5f;
            }
            return new Dual2f(r, dnd0 * c0.dx, dnd0 * c0.dy);
        }

        private static Dual2f simplex_noise_dual(bool unsigned_result, int seed, Dual2f c0, Dual2f c1)
        {
            float dnd0;
            float dnd1;
            float r = SimplexNoiseFuncs.simplexnoise2(c0.x, c1.x, seed, &dnd0, &dnd1);
            if (unsigned_result)
            {
                r = 0.5f * (r + 1.0f);
                dnd0 *= 0.5f;
                dnd1 *= 0.5f;
            }
            return new Dual2f(r, dnd0 * c0.dx + dnd1 * c1.dx, dnd0 * c0.dy + dnd1 * c1.dy);
        }

        private static Dual2f simplex_noise_dual(bool unsigned_result, int seed, Dual2f c0, Dual2f c1, Dual2f c2)
        {
            float dnd0;
            float dnd1;
            float dnd2;
            float r = SimplexNoiseFuncs.simplexnoise3(c0.x, c1.x, c2.x, seed, &dnd0, &dnd1, &dnd2);
            if (unsigned_result)
            {
                r = 0.5f * (r + 1.0f);
                dnd0 *= 0.5f;
                dnd1 *= 0.5f;
                dnd2 *= 0.5f;
            }
            return new Dual2f(r, dnd0 * c0.dx + dnd1 * c1.dx + dnd2 * c2.dx, dnd0 * c0.dy + dnd1 * c1.dy + dnd2 * c2.dy);
        }

        private static Dual2f simplex_noise_dual(bool unsigned_result, int seed, Dual2f c0, Dual2f c1, Dual2f c2, Dual2f c3)
        {
            float dnd0;
            float dnd1;
            float dnd2;
            float dnd3;
            float r = SimplexNoiseFuncs.simplexnoise4(c0.x, c1.x, c2.x, c3.x, seed, &dnd0, &dnd1, &dnd2, &dnd3);
            if (unsigned_result)
            {
                r = 0.5f * (r + 1.0f);
                dnd0 *= 0.5f;
                dnd1 *= 0.5f;
                dnd2 *= 0.5f;
                dnd3 *= 0.5f;
            }
            return new Dual2f(r, dnd0 * c0.dx + dnd1 * c1.dx + dnd2 * c2.dx + dnd3 * c3.dx, dnd0 * c0.dy + dnd1 * c1.dy + dnd2 * c2.dy + dnd3 * c3.dy);
        }

