        public static void osl_noise_dvdf(void* r, void* x)
        {
            OslNoise.PerlinHash ph = OslNoise.PerlinHash.nonperiodic();
            float* result = (float*)r;
            OslNoise.perlinv(ph, result, *(Dual2f*)x);
            for (int i = 0; i < 3; ++i)
            {
                result[i] = 0.5f * (result[i] + 1.0f);
                result[3 + i] = result[3 + i] * 0.5f;
                result[6 + i] = result[6 + i] * 0.5f;
            }
        }

