        public static void osl_genericnoise_dfdf(ulong name, void* r, void* x, void* sg, void* opt)
        {
            if (name == Hashes.uperlin || name == Hashes.noise)
            {
                osl_noise_dfdf(r, x);
            }
            else if (name == Hashes.perlin || name == Hashes.snoise)
            {
                osl_snoise_dfdf(r, x);
            }
            else if (name == Hashes.simplexnoise || name == Hashes.simplex)
            {
                osl_simplexnoise_dfdf(r, x);
            }
            else if (name == Hashes.usimplexnoise || name == Hashes.usimplex)
            {
                osl_usimplexnoise_dfdf(r, x);
            }
            else if (name == Hashes.cell)
            {
                *(float*)r = osl_cellnoise_ff(*(float*)x);
                ((Dual2f*)r)->clear_d();
            }
            else if (name == Hashes.gabor)
            {
                *(Dual2f*)r = GaborNoise.gabor(*(Dual2f*)x, (NoiseParams*)opt);
            }
            else if (name == Hashes.@null)
            {
                osl_nullnoise_dfdf(r, x);
            }
            else if (name == Hashes.unull)
            {
                osl_unullnoise_dfdf(r, x);
            }
            else if (name == Hashes.hash)
            {
                *(float*)r = osl_hashnoise_ff(*(float*)x);
                ((Dual2f*)r)->clear_d();
            }
            else
            {
                if (unknown_noise_type_hook != null)
                {
                    unknown_noise_type_hook(name);
                }
            }
        }

