        public static void osl_init_noise_options(void* sg, void* opt)
        {
            *(NoiseParams*)opt = NoiseParams.create_default();
        }

        public static void osl_noiseparams_set_anisotropic(void* opt, int a)
        {
            ((NoiseParams*)opt)->anisotropic = a;
        }

        public static void osl_noiseparams_set_do_filter(void* opt, int a)
        {
            ((NoiseParams*)opt)->do_filter = a;
        }

        public static void osl_noiseparams_set_direction(void* opt, void* dir)
        {
            ((NoiseParams*)opt)->direction = *(Vec3*)dir;
        }

        public static void osl_noiseparams_set_bandwidth(void* opt, float b)
        {
            ((NoiseParams*)opt)->bandwidth = b;
        }

        public static void osl_noiseparams_set_impulses(void* opt, float i)
        {
            ((NoiseParams*)opt)->impulses = i;
        }

        public static int osl_hash_ii(int x)
        {
            return OslNoise.inthashi(x);
        }

        public static int osl_hash_if(float x)
        {
            return OslNoise.inthashf(x);
        }

        public static int osl_hash_iff(float x, float y)
        {
            return OslNoise.inthashf(x, y);
        }

        public static int osl_hash_iv(void* x)
        {
            return OslNoise.inthashf((float*)x);
        }

        public static int osl_hash_ivf(void* x, float y)
        {
            return OslNoise.inthashf((float*)x, y);
        }
    }
